    const SPEEDS = { slow: 55, normal: 32, fast: 16 };
    const state = {
      open:false, script:'', beats:[], idx:0, flags:{}, backlog:[],
      typingText:'', timer:0, auto:false, autoTimer:0, skip:false, skipTimer:0,
      speed:'normal', bg:'', title:'', menuOpen:false, landscape:false, drawerOpen:false,
      pages:[''], pageIdx:0, rotatedByApp:false, cg:'', sprites:{}, assets:{}
    };

    /* ---------- 配置读写 ---------- */
    function loadCfg(){
      const c = api.getCfg() || {};
      return (c && c.galPlayer) ? c.galPlayer : {};
    }
    function saveCfgData(patch){
      const c = api.getCfg();
      c.galPlayer = Object.assign({}, c.galPlayer || {}, patch);
      api.saveCfg();
    }
    function saveGame(){
      const c = api.getCfg();
      c.galSave = { idx: state.idx, flags: state.flags, at: Date.now(), script: state.script.slice(0, 60000) };
      api.saveCfg();
      api.toast('已存档');
    }
    function loadGame(){
      const c = api.getCfg();
      const s = c && c.galSave;
      if (!s){ api.toast('没有存档'); return; }
      if (s.script) state.script = s.script;
      buildBeats();
      state.flags = s.flags || {};
      state.idx = Math.max(0, Math.min(s.idx || 0, state.beats.length - 1));
      state.backlog = [];
      state.ended = false;
      hideTitle();
      renderBeat(true);
      api.toast('已读档');
    }

    /* ---------- 剧本解析 ---------- */
    function buildBeats(){
      const lines = String(state.script || '').split('\n');
      const beats = [];
      for (let i = 0; i < lines.length; i++){
        const raw = lines[i].replace(/\s+$/,'');
        if (!raw.trim()) continue;
        if (raw.startsWith('#')){ beats.push({ type:'chapter', text: raw.replace(/^#+\s*/,'') }); continue; }
        if (raw.startsWith('@bg')){ beats.push({ type:'bg', name: raw.replace(/^@bg\s*/,'').trim() }); continue; }
        if (raw.startsWith('@cg')){
          const v = raw.replace(/^@cg\s*/,'').trim();
          beats.push({ type:'cg', name: (/^(off|none|)$/i.test(v)) ? '' : v });
          continue;
        }
        if (raw.startsWith('@show')){
          const parts = raw.replace(/^@show\s*/,'').trim().split(/\s+/);
          beats.push({ type:'show', char: parts[0] || 'deep', expr: parts[1] || 'idle' });
          continue;
        }
        if (raw.startsWith('@hide')){
          beats.push({ type:'hide', char: (raw.replace(/^@hide\s*/,'').trim() || 'deep') });
          continue;
        }
        if (raw.startsWith('@ending')){ beats.push({ type:'ending', text: raw.replace(/^@ending\s*/,'').trim() }); continue; }
        if (raw.startsWith('@')) continue;
        if (/^选项[:：]?$/.test(raw.trim())){
          const opts = [];
          let j = i + 1;
          while (j < lines.length){
            const o = lines[j].replace(/\s+$/,'');
            const m = /^([①②③④⑤⑥]|[-*]|\d+[.、])\s*(.+)$/.exec(o.trim());
            if (!m) break;
            opts.push({ label: m[2].trim() });
            j++;
          }
          if (opts.length) beats.push({ type:'choice', options: opts });
          continue;
        }
        const m = /^(【[^】]+】)?\s*([^：:\s]{1,8})[：:]\s*(.+)$/.exec(raw);
        if (m && !/^(选项|旁白)$/.test(m[2])){
          beats.push({ type:'say', who: m[2].trim(), text: m[3].trim(), narr:false });
          continue;
        }
        beats.push({ type:'say', who:'', text: raw.replace(/^[▲]\s*/,''), narr:true });
      }
      state.beats = beats;
      const ch = beats.find(b => b.type === 'chapter');
      state.title = ch ? ch.text : '未命名剧本';
    }

    /* ---------- DOM ---------- */
    let root, elWrap, elStage, elBg, elCg, elSprite, elBox, elName, elText, elNext, elChoice,
        elTitle, elBacklog, elChip, elMenu, elDrawer, elDrawerPanel, elHandle;

    function buildUI(){
      if (root) return;
      root = document.createElement('div');
      root.id = 'galRoot';
      root.innerHTML = `
        <div class="gal-rot" id="galRot">
          <div class="gal-stage" id="galStage">
            <div class="gal-bg" id="galBg"></div>
            <div class="gal-cg" id="galCg"></div>
            <img class="gal-sprite" id="galSprite" alt="">
            <div class="gal-chip" id="galChip"></div>

            <div class="gal-title" id="galTitle">
              <div class="gal-t-kicker">VISUAL NOVEL</div>
              <div class="gal-t-name" id="galTitleName">序章　名字</div>
              <div class="gal-t-sub">《深》 · 病娇向心理恐怖</div>
              <div class="gal-t-btns">
                <button class="gal-btn primary" id="galStart">开始游戏</button>
                <button class="gal-btn" id="galContinue">继续</button>
                <button class="gal-btn" id="galClear">清空存档</button>
              </div>
              <div class="gal-t-tip">点击画面继续　·　A 自动　·　S 存档　·　L 读档　·　H 回看</div>
            </div>

            <div class="gal-dialog" id="galDialog">
              <div class="gal-name" id="galName"></div>
              <div class="gal-text" id="galText"></div>
              <div class="gal-next" id="galNext">▼</div>

            </div>

            <div class="gal-choices" id="galChoice" style="display:none"></div>

            <div class="gal-menu" id="galMenu" style="display:none">
              <div class="gal-menu-title">菜单</div>
              <div class="gal-menu-row"><span>文字速度</span>
                <select id="galMenuSpeed">
                  <option value="slow">慢</option>
                  <option value="normal">正常</option>
                  <option value="fast">快</option>
                </select>
              </div>
              <div class="gal-menu-row"><span>横向显示</span>
                <button class="gal-mini" id="galMenuRot">切换</button>
              </div>
              <div class="gal-menu-btns">
                <button class="gal-btn" id="galMenuSave">存档</button>
                <button class="gal-btn" id="galMenuLoad">读档</button>
                <button class="gal-btn" id="galMenuLog">回看</button>
                <button class="gal-btn" id="galMenuTitle">返回标题</button>
                <button class="gal-btn" id="galMenuExit">关闭</button>
              </div>
            </div>

            <div class="gal-backlog" id="galBacklog" style="display:none"></div>
          </div>
            <div class="gal-drawer" id="galDrawer">
              <button class="gal-handle" id="galHandle">菜单</button>
              <div class="gal-drawer-panel" id="galDrawerPanel">
                <button data-a="auto">自动</button>
                <button data-a="skip">快进</button>
                <button data-a="log">回看</button>
                <button data-a="save">存档</button>
                <button data-a="load">读档</button>
                <button data-a="speed">文字速度</button>
                <button data-a="rot">横屏切换</button>
                <button data-a="title">返回标题</button>
                <button data-a="close">关闭</button>
              </div>
            </div>
        </div>`;
      document.body.appendChild(root);

      elWrap = root.querySelector('#galRot');
      elStage = root.querySelector('#galStage');
      elBg = root.querySelector('#galBg');
      elCg = root.querySelector('#galCg');
      elSprite = root.querySelector('#galSprite');
      elBox = root.querySelector('#galDialog');
      elName = root.querySelector('#galName');
      elText = root.querySelector('#galText');
      elNext = root.querySelector('#galNext');
      elChoice = root.querySelector('#galChoice');
      elTitle = root.querySelector('#galTitle');
      elBacklog = root.querySelector('#galBacklog');
      elChip = root.querySelector('#galChip');
      elMenu = root.querySelector('#galMenu');
      elDrawer = root.querySelector('#galDrawer');
      elDrawerPanel = root.querySelector('#galDrawerPanel');
      elHandle = root.querySelector('#galHandle');

      root.querySelector('#galStart').onclick = (e) => { e.stopPropagation(); startGame(); };
      root.querySelector('#galContinue').onclick = (e) => { e.stopPropagation(); loadGame(); };
      root.querySelector('#galClear').onclick = (e) => {
        e.stopPropagation();
        const c = api.getCfg(); delete c.galSave; api.saveCfg(); api.toast('存档已清空');
      };

      elStage.addEventListener('click', (e) => {
        if (e.target.closest('.gal-drawer') || e.target.closest('.gal-menu') ||
            e.target.closest('.gal-choices') || e.target.closest('.gal-backlog') ||
            e.target.closest('.gal-title')) return;
        if (state.menuOpen){ closeMenu(); return; }
        advance();
      });

      function setDrawer(open){
        state.drawerOpen = !!open;
        elDrawer.classList.toggle('open', state.drawerOpen);
      }
      elHandle.addEventListener('click', (e) => { e.stopPropagation(); setDrawer(!state.drawerOpen); });
      elDrawerPanel.addEventListener('click', (e) => {
        const btn = e.target.closest('button'); if (!btn) return;
        e.stopPropagation();
        const a = btn.getAttribute('data-a');
        if (a === 'auto'){ toggleAuto(); markDrawer(btn, state.auto); }
        else if (a === 'skip'){ toggleSkip(); markDrawer(btn, state.skip); }
        else if (a === 'log'){ setDrawer(false); toggleBacklog(true); }
        else if (a === 'save') saveGame();
        else if (a === 'load'){ loadGame(); setDrawer(false); }
        else if (a === 'speed'){ cycleSpeed(); }
        else if (a === 'rot'){ state.forceLandscape = !state.forceLandscape; layout(); setDrawer(false); }
        else if (a === 'title'){ setDrawer(false); showTitle(); }
        else if (a === 'close'){ close(); }
      });
      function markDrawer(btn, on){ btn.classList.toggle('on', !!on); }
      window.__galSetDrawer = setDrawer;
      root.querySelector('#galMenuSpeed').onchange = function(){
        state.speed = this.value; saveCfgData({ speed: this.value });
      };
      root.querySelector('#galMenuRot').onclick = (e) => { e.stopPropagation(); state.forceLandscape = !state.forceLandscape; layout(); };
      root.querySelector('#galMenuSave').onclick = (e) => { e.stopPropagation(); saveGame(); };
      root.querySelector('#galMenuLoad').onclick = (e) => { e.stopPropagation(); loadGame(); closeMenu(); };
      root.querySelector('#galMenuLog').onclick = (e) => { e.stopPropagation(); closeMenu(); toggleBacklog(true); };
      root.querySelector('#galMenuTitle').onclick = (e) => { e.stopPropagation(); closeMenu(); showTitle(); };
      root.querySelector('#galMenuExit').onclick = (e) => { e.stopPropagation(); close(); };
    }

    /* ---------- 横屏布局 ---------- */
    function layout(){
      if (!root) return;
      const vw = window.innerWidth, vh = window.innerHeight;
      const portrait = vh > vw;
      // 竖屏时把整个舞台旋转 90°，模拟横屏
      state.landscape = state.forceLandscape !== false;
      const rot = portrait && state.landscape && !state.rotatedByApp;
      elWrap.classList.toggle('rot', rot);
      root.classList.toggle('is-portrait', portrait);
      const W = rot ? vh : vw;
      const H = rot ? vw : vh;
      elWrap.style.width = W + 'px';
      elWrap.style.height = H + 'px';
      // 舞台按 16:9 letterbox 居中，避免手机宽屏把画面上下裁掉
      const boxW = Math.min(W, H * 16 / 9);
      const boxH = boxW * 9 / 16;
      if (elStage){
        elStage.style.width = boxW + 'px';
        elStage.style.height = boxH + 'px';
        elStage.style.left = ((W - boxW) / 2) + 'px';
        elStage.style.top = ((H - boxH) / 2) + 'px';
        elStage.style.right = 'auto';
        elStage.style.bottom = 'auto';
      }
      const fs = Math.max(13, Math.round(H * 0.036));
      root.style.setProperty('--gal-fs', fs + 'px');
      root.style.setProperty('--gal-dlg-h', Math.round(H * 0.27) + 'px');
      root.style.setProperty('--gal-name-fs', Math.round(H * 0.018) + 'px');
    }
    window.addEventListener('resize', function(){ if (state.open) layout(); });

    /* ---------- 播放 ---------- */
    function startGame(){
      buildBeats();
      state.idx = 0; state.flags = {}; state.backlog = []; state.ended = false;
      state.cg = ''; state.sprites = {}; paintCg(); paintSprite();
      hideTitle(); renderBeat(true);
    }
    function hideTitle(){ if (elTitle) elTitle.style.display = 'none'; }
    function showTitle(){
      if (!elTitle) return;
      elTitle.style.display = '';
      root.querySelector('#galTitleName').textContent = state.title || '未命名剧本';
      elChoice.style.display = 'none';
      elBacklog.style.display = 'none';
      elBox.style.visibility = 'hidden';
      elChip.style.display = 'none';
    }
    function currentBeat(){ return state.beats[state.idx] || null; }

    function renderBeat(instant){
      const b = currentBeat();
      if (!b){ finish(); return; }
      if (b.type === 'chapter'){ state.idx++; renderBeat(instant); return; }
      if (b.type === 'bg'){ state.bg = b.name; paintBg(true); state.idx++; renderBeat(instant); return; }
      if (b.type === 'cg'){ state.cg = b.name; paintCg(); state.idx++; renderBeat(instant); return; }
      if (b.type === 'show'){ state.sprites[b.char] = b.expr; paintSprite(); state.idx++; renderBeat(instant); return; }
      if (b.type === 'hide'){ delete state.sprites[b.char]; paintSprite(); state.idx++; renderBeat(instant); return; }
      if (b.type === 'ending'){ finish(b.text); return; }
      if (b.type === 'choice'){ renderChoice(b); return; }
      elBox.style.visibility = 'visible';
      elChoice.style.display = 'none';
      if (b.narr){ elName.style.display = 'none'; }
      else { elName.style.display = ''; elName.textContent = b.who || ''; }
      state.backlog.push({ who: b.who || '旁白', text: b.text });
      if (state.backlog.length > 300) state.backlog.shift();
      state.pages = splitPages(b.text);
      state.pageIdx = 0;
      typeText(state.pages[0], instant);
    }


    /* 素材地址：插件完全自带（bundled assets），不依赖 App 里的文件 */
    function assetSrc(name){
      return (state.assets && state.assets[name]) || api.asset(name) || '';
    }

    /* 计算一行能放多少字、一屏能放几行，超长就按句号切页 */
    function splitPages(text){
      const t = String(text || '');
      if (!t) return [''];
      ensureLayout();
      const fs = parseFloat(getComputedStyle(elText).fontSize) || 18;
      const w = elText.clientWidth || (elStage.clientWidth * 0.9);
      const perLine = Math.max(12, Math.floor(w / (fs * 1.02)));
      const boxH = Math.max(60, elStage.clientHeight * 0.46 - elName.offsetHeight - 40);
      const lines = Math.max(2, Math.floor(boxH / (fs * 1.82)));
      const cap = Math.max(40, Math.floor(perLine * lines * 0.94));
      if (t.length <= cap) return [t];
      // 按标点切成句子，再按容量拼页
      const parts = t.split(/(?<=[。！？…；!?;\n])/).filter(function(x){ return x !== ''; });
      const pages = []; let cur = '';
      for (let i = 0; i < parts.length; i++){
        const seg = parts[i];
        if (cur.length + seg.length > cap && cur) { pages.push(cur.trim()); cur = seg; }
        else cur += seg;
      }
      if (cur.trim()) pages.push(cur.trim());
      return pages.length ? pages : [t];
    }

    /* 文字塞不下时自动缩小字号（最多缩到 12px） */
    function fitDialogText(){
      elText.style.fontSize = '';
      const stageH = elStage.clientHeight || 400;
      const budget = stageH * 0.42 - (elName.offsetHeight || 0) - 26;
      let fs = parseFloat(getComputedStyle(elText).fontSize) || 18;
      let guard = 0;
      while (elText.scrollHeight > budget && fs > 12 && guard++ < 60){
        fs -= 0.5;
        elText.style.fontSize = fs.toFixed(1) + 'px';
      }
    }

    function ensureLayout(){ if (elStage && !elStage.clientHeight) layout(); }

    function typeText(text, instant){
      clearInterval(state.timer);
      state.typingText = text;
      const delay = state.skip ? 0 : (SPEEDS[state.speed] || SPEEDS.normal);
      if (instant || delay === 0){ elText.textContent = text; fitDialogText(); elNext.style.opacity = '1'; afterType(); return; }
      let i = 0;
      elText.textContent = '';
      elNext.style.opacity = '0';
      state.timer = setInterval(function(){
        i += 1;
        elText.textContent = text.slice(0, i);
        if (i >= text.length){
          clearInterval(state.timer); state.timer = 0;
          fitDialogText();
          elNext.style.opacity = '1';
          afterType();
        }
      }, delay);
    }
    function afterType(){
      if (state.auto) scheduleAuto();
      if (state.skip) scheduleSkip();
    }
    function skipTyping(){
      if (!state.timer) return false;
      clearInterval(state.timer); state.timer = 0;
      elText.textContent = state.typingText;
      elNext.style.opacity = '1';
      afterType();
      return true;
    }
    function advance(){
      if (!state.open) return;
      if (elBacklog.style.display !== 'none'){ elBacklog.style.display = 'none'; return; }
      if (skipTyping()) return;
      const b = currentBeat();
      if (!b) return;
      if (b.type === 'choice') return;
      if (state.pages && state.pageIdx < state.pages.length - 1){
        state.pageIdx++;
        elText.textContent = state.pages[state.pageIdx];
        fitDialogText();
        elNext.style.opacity = '1';
        return;
      }
      state.idx++;
      renderBeat(false);
      updateChip();
    }
    function scheduleAuto(){
      if (!state.auto) return;
      clearTimeout(state.autoTimer);
      state.autoTimer = setTimeout(function(){ if (state.auto) advance(); }, 1200);
    }
    function scheduleSkip(){
      if (!state.skip) return;
      clearTimeout(state.skipTimer);
      state.skipTimer = setTimeout(function(){ if (state.skip) advance(); }, 60);
    }
    function toggleAuto(){
      state.auto = !state.auto;
      const ab = elDrawerPanel.querySelector('[data-a="auto"]'); if (ab) ab.classList.toggle('on', state.auto);
      api.toast(state.auto ? '自动：开' : '自动：关');
      if (state.auto && !state.timer) scheduleAuto();
    }
    function toggleSkip(){
      state.skip = !state.skip;
      const sb = elDrawerPanel.querySelector('[data-a="skip"]'); if (sb) sb.classList.toggle('on', state.skip);
      api.toast(state.skip ? '快进：开' : '快进：关');
      if (state.skip) { skipTyping(); scheduleSkip(); }
    }

    function renderChoice(b){
      elChoice.style.display = '';
      elBox.style.visibility = 'hidden';
      elChoice.innerHTML = '<div class="gal-c-kicker">选择</div>';
      b.options.forEach(function(o, i){
        const btn = document.createElement('button');
        btn.className = 'gal-c-btn';
        btn.innerHTML = '<span>' + '①②③④⑤⑥'[i] + '</span>' + escapeHtml(o.label);
        btn.onclick = function(ev){
          ev.stopPropagation();
          state.flags['c' + state.idx] = i;
          state.backlog.push({ who:'选择', text:o.label });
          state.idx++;
          elChoice.style.display = 'none';
          renderBeat(false);
        };
        elChoice.appendChild(btn);
      });
    }

    function finish(text){
      state.ended = true;
      elChoice.style.display = '';
      elChoice.innerHTML = '<div class="gal-c-kicker">本章结束</div>'
        + '<div class="gal-c-end">' + escapeHtml(text || '') + '</div>'
        + '<button class="gal-c-btn" id="galAgain"><span>↻</span>重新开始</button>'
        + '<button class="gal-c-btn" id="galBackTitle"><span>⌂</span>返回标题</button>';
      elBox.style.visibility = 'hidden';
      elChoice.querySelector('#galAgain').onclick = (e) => { e.stopPropagation(); startGame(); };
      elChoice.querySelector('#galBackTitle').onclick = (e) => { e.stopPropagation(); showTitle(); };
    }

    function paintBg(fade){
      const name = state.bg;
      const asset = name ? assetSrc(name) : '';
      if (asset){
        elBg.style.backgroundImage = 'url("' + asset + '")';
        elBg.classList.remove('empty');
        if (fade){
          elBg.style.transition = 'none'; elBg.style.opacity = '0';
          requestAnimationFrame(function(){ elBg.style.transition = 'opacity .22s ease'; elBg.style.opacity = '1'; });
        }
      } else {
        elBg.style.backgroundImage = '';
        elBg.classList.add('empty');
      }
    }
    function paintCg(){
      const name = state.cg;
      const asset = name ? assetSrc(name) : '';
      if (asset){
        elCg.style.backgroundImage = 'url("' + asset + '")';
        elCg.classList.add('show');
      } else {
        elCg.style.backgroundImage = '';
        elCg.classList.remove('show');
      }
    }
    function paintSprite(){
      const expr = state.sprites && state.sprites.deep;
      const asset = expr ? assetSrc('sprite_' + expr) : '';
      if (asset){ elSprite.src = asset; elSprite.classList.add('show'); }
      else { elSprite.removeAttribute('src'); elSprite.classList.remove('show'); }
    }

    function updateChip(){
      const b = currentBeat();
      elChip.style.display = 'none';
    }

    function toggleBacklog(force){
      const show = (typeof force === 'boolean') ? force : (elBacklog.style.display === 'none');
      if (!show){ elBacklog.style.display = 'none'; return; }
      elBacklog.innerHTML = '<div class="gal-c-kicker">回 看</div>' +
        state.backlog.slice(-100).map(function(x){
          return '<div class="gal-log"><b>' + escapeHtml(x.who) + '</b><span>' + escapeHtml(x.text) + '</span></div>';
        }).join('') +
        '<div class="gal-log-hint">点任意处关闭</div>';
      elBacklog.style.display = '';
    }

    function cycleSpeed(){
      const order = ['slow','normal','fast'];
      state.speed = order[(order.indexOf(state.speed) + 1) % order.length];
      saveCfgData({ speed: state.speed });
      api.toast('文字速度：' + ({slow:'慢',normal:'正常',fast:'快'}[state.speed]));
    }

    function toggleMenu(force){
      const show = (typeof force === 'boolean') ? force : !state.menuOpen;
      state.menuOpen = show;
      elMenu.style.display = show ? '' : 'none';
      const sel = root.querySelector('#galMenuSpeed');
      if (sel) sel.value = state.speed;
    }
    function closeMenu(){ toggleMenu(false); }

    function escapeHtml(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

    function open(){
      buildUI();
      state.open = true;
      root.style.display = 'block';
      const conf = loadCfg();
      state.speed = conf.speed || 'normal';
      state.script = (conf.script || '').trim() || DEMO_SCRIPT;
      try{ state.assets = api.assets() || {}; }catch(e){ state.assets = {}; }
      window.__galDebug = { state: state, assetKeys: Object.keys(state.assets), script: state.script.slice(0,60) };
      buildBeats();
      paintBg();
      // 真·横屏：优先用 App 的 NativeSys 桥；否则试全屏+orientation lock；最后退回 CSS 旋转
      state.rotatedByApp = false;
      try{
        if (window.NativeSys && NativeSys.setOrientation){
          NativeSys.setOrientation('landscape');
          state.rotatedByApp = true;
        }
      }catch(e){}
      if (!state.rotatedByApp){
        try{
          const de = document.documentElement;
          if (de.requestFullscreen) de.requestFullscreen().catch(function(){});
          if (screen.orientation && screen.orientation.lock) {
            screen.orientation.lock('landscape').then(function(){ state.rotatedByApp = true; layout(); }).catch(function(){});
          }
        }catch(e){}
      }
      setTimeout(function(){ if (state.open) layout(); }, 260);
      layout();
      showTitle();
      try{ window.__galSetDrawer && window.__galSetDrawer(false); }catch(e){}
    }
    function close(){
      state.open = false;
      if (root) root.style.display = 'none';
      clearInterval(state.timer); clearTimeout(state.autoTimer); clearTimeout(state.skipTimer);
      try{ if (window.NativeSys && NativeSys.setOrientation) NativeSys.setOrientation('portrait'); }catch(e){}
      try{ if (window.NativeSys && NativeSys.setImmersive) NativeSys.setImmersive(false); }catch(e){}
      try{ if (screen.orientation && screen.orientation.unlock) screen.orientation.unlock(); }catch(e){}
      try{ if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(function(){}); }catch(e){}
    }

    document.addEventListener('keydown', function(e){
      if (!state.open) return;
      if (e.key === ' ' || e.key === 'Enter' || e.key === 'ArrowRight'){ e.preventDefault(); advance(); }
      else if (e.key === 'a' || e.key === 'A') toggleAuto();
      else if (e.key === 's' || e.key === 'S') saveGame();
      else if (e.key === 'l' || e.key === 'L') loadGame();
      else if (e.key === 'h' || e.key === 'H') toggleBacklog();
      else if (e.key === 'Escape') close();
    });

